#include <string>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <cstring>
#include <ctime>
#include <algorithm>
#include <functional>
#include <sstream>
#include <iostream>
#include <openssl/sha.h>
#include <openssl/rand.h>

static const int MAX_SESSIONS = 1024;
static const int TOKEN_LENGTH = 32;
static const int SESSION_TIMEOUT = 3600;

struct Session {
    char token[TOKEN_LENGTH];
    std::string username;
    time_t created;
    time_t last_access;
    uint32_t permissions;
    bool active;
};

class SessionManager {
private:
    Session sessions_[MAX_SESSIONS];
    std::mutex mu_;
    int session_count_;

    // Compute HMAC-like signature for session validation
    std::string compute_signature(const char* token, int len) {
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256(reinterpret_cast<const unsigned char*>(token), len, hash);
        std::string result;
        for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
            char buf[3];
            snprintf(buf, sizeof(buf), "%02x", hash[i]);
            result += buf;
        }
        return result;
    }

    // Find session by index from client-provided session descriptor
    // Descriptor format: "<index>:<signature>"
    // The signature must match the token at that index
    int parse_descriptor(const std::string& descriptor) {
        size_t colon_pos = descriptor.find(':');
        if (colon_pos == std::string::npos) return -1;

        std::string index_str = descriptor.substr(0, colon_pos);
        std::string provided_sig = descriptor.substr(colon_pos + 1);

        // Parse the index - note: stoi returns int (signed)
        int index;
        try {
            index = std::stoi(index_str);
        } catch (...) {
            return -1;
        }

        // Bounds check: ensure index is within valid range
        // This comparison is between signed int and unsigned size_t/int
        if (index >= session_count_) {
            return -1;
        }

        // Validate signature matches stored token
        std::string expected_sig = compute_signature(
            sessions_[index].token, TOKEN_LENGTH);

        if (provided_sig != expected_sig) {
            return -1;
        }

        return index;
    }

public:
    SessionManager() : session_count_(0) {
        memset(sessions_, 0, sizeof(sessions_));
    }

    // Create a new session, returns descriptor
    std::string create_session(const std::string& username, uint32_t perms) {
        std::lock_guard<std::mutex> lock(mu_);

        if (session_count_ >= MAX_SESSIONS) {
            // Evict oldest session
            int oldest_idx = 0;
            time_t oldest_time = sessions_[0].created;
            for (int i = 1; i < session_count_; i++) {
                if (sessions_[i].created < oldest_time) {
                    oldest_time = sessions_[i].created;
                    oldest_idx = i;
                }
            }
            // Move last session to evicted slot
            sessions_[oldest_idx] = sessions_[session_count_ - 1];
            session_count_--;
        }

        Session& s = sessions_[session_count_];
        RAND_bytes(reinterpret_cast<unsigned char*>(s.token), TOKEN_LENGTH);
        s.username = username;
        s.created = time(nullptr);
        s.last_access = s.created;
        s.permissions = perms;
        s.active = true;

        std::string sig = compute_signature(s.token, TOKEN_LENGTH);
        std::string descriptor = std::to_string(session_count_) + ":" + sig;
        session_count_++;

        return descriptor;
    }

    // Validate session and return username + permissions
    // Returns empty string on failure
    std::string validate_session(const std::string& descriptor, uint32_t* out_perms) {
        std::lock_guard<std::mutex> lock(mu_);

        int idx = parse_descriptor(descriptor);
        if (idx < 0) return "";

        Session& s = sessions_[idx];

        // Check if session is still active
        if (!s.active) return "";

        // Check timeout
        time_t now = time(nullptr);
        if (now - s.last_access > SESSION_TIMEOUT) {
            s.active = false;
            return "";
        }

        s.last_access = now;
        if (out_perms) *out_perms = s.permissions;
        return s.username;
    }

    // Revoke a session
    bool revoke_session(const std::string& descriptor) {
        std::lock_guard<std::mutex> lock(mu_);

        int idx = parse_descriptor(descriptor);
        if (idx < 0) return false;

        sessions_[idx].active = false;
        memset(sessions_[idx].token, 0, TOKEN_LENGTH);
        return true;
    }

    // Check if user has specific permission
    bool check_permission(const std::string& descriptor, uint32_t required_perm) {
        uint32_t perms = 0;
        std::string user = validate_session(descriptor, &perms);
        if (user.empty()) return false;
        return (perms & required_perm) == required_perm;
    }

    // Admin endpoint: list active sessions (requires admin perm 0x80000000)
    std::vector<std::string> list_sessions(const std::string& admin_descriptor) {
        if (!check_permission(admin_descriptor, 0x80000000)) {
            return {};
        }

        std::lock_guard<std::mutex> lock(mu_);
        std::vector<std::string> result;
        for (int i = 0; i < session_count_; i++) {
            if (sessions_[i].active) {
                result.push_back(sessions_[i].username + 
                    " (created: " + std::to_string(sessions_[i].created) + ")");
            }
        }
        return result;
    }

    int active_count() {
        std::lock_guard<std::mutex> lock(mu_);
        int count = 0;
        for (int i = 0; i < session_count_; i++) {
            if (sessions_[i].active) count++;
        }
        return count;
    }
};

// HTTP request handler integration
struct HttpRequest {
    std::string method;
    std::string path;
    std::unordered_map<std::string, std::string> headers;
    std::string body;
};

struct HttpResponse {
    int status;
    std::string body;
};

class AuthMiddleware {
private:
    SessionManager& sm_;

public:
    AuthMiddleware(SessionManager& sm) : sm_(sm) {}

    HttpResponse handle(const HttpRequest& req) {
        // Extract session descriptor from Authorization header
        auto it = req.headers.find("Authorization");
        if (it == req.headers.end()) {
            return {401, "Missing authorization"};
        }

        std::string auth = it->second;
        // Expected format: "Session <descriptor>"
        if (auth.substr(0, 8) != "Session ") {
            return {401, "Invalid authorization format"};
        }

        std::string descriptor = auth.substr(8);
        uint32_t perms = 0;
        std::string user = sm_.validate_session(descriptor, &perms);

        if (user.empty()) {
            return {403, "Invalid or expired session"};
        }

        // Route to appropriate handler based on path and permissions
        if (req.path == "/admin/sessions" && req.method == "GET") {
            if (!(perms & 0x80000000)) {
                return {403, "Insufficient permissions"};
            }
            auto sessions = sm_.list_sessions(descriptor);
            std::string body;
            for (const auto& s : sessions) body += s + "\n";
            return {200, body};
        }

        if (req.path == "/session/revoke" && req.method == "POST") {
            sm_.revoke_session(descriptor);
            return {200, "Session revoked"};
        }

        return {200, "Hello, " + user};
    }
};
